Worker_Thread_Data :: struct {
	run: bool,
	thread: ^thread.Thread,
}

worker_thread_proc :: proc(t: ^thread.Thread) {
	d := (^Worker_Thread_Data)(t.data)
	for d.run {
		fmt.println("working")
	}
}

